export function formatHits(hits: Hit[], maxResults: number): string {
  if (hits.length === 0) return "No matches.";
  const shown = hits.slice(0, maxResults);
  const lines = shown.map((hit) => `${hit.file}:${hit.line}: ${hit.text}`);
  if (hits.length > maxResults) {
    lines.push(
      `[truncated: showing ${maxResults} of ${hits.length} matches; narrow the path or raise max_results]`,
    );
  }
  return lines.join("\n");
}

function formatResult(
  hits: Hit[],
  maxResults: number,
  count: boolean,
): string {
  return count ? formatCounts(hits, maxResults) : formatHits(hits, maxResults);
}

export function formatCounts(hits: Hit[], maxResults: number): string {
  if (hits.length === 0) return "No matches.";
  const counts = new Map<string, number>();
  for (const hit of hits) {
    counts.set(hit.file, (counts.get(hit.file) ?? 0) + 1);
  }
  const files = [...counts.keys()];
  const shown = files.slice(0, maxResults);
  const lines = shown.map((file) => `${file}: ${counts.get(file) ?? 0}`);
  if (files.length > maxResults) {
    lines.push(
      `[truncated: showing ${maxResults} of ${files.length} files; narrow the path or raise max_results]`,
    );
  }
  return lines.join("\n");
}

